utton type="button" class="admin-jalali-clear" aria-label="پاک کردن {{ $dateLabel }}" @click="clear()" :disabled="!values['{{ $dateKey }}']"><x-icon name="x" size="16" /></button></div><span class="field-hint">{{ ($withTime??false)?'تاریخ شمسی · ساعت تهران (۲۴ ساعته)':'تاریخ شمسی' }}</span><span class="field-error" x-show="dateError" x-text="dateError" x-cloak></span>
<div class="admin-jalali-popover" x-cloak x-show="opened" x-transition @click.outside="opened=false" @keydown.escape.stop="opened=false"><div class="admin-jalali-calendar-dialog" role="dialog" aria-label="تقویم شمسی {{ $dateLabel }}"><div class="admin-jalali-calendar-heading"><button type="button" @click="month(-1)" aria-label="ماه قبل"><x-icon name="chevron-right" size="20" /></button><h2 x-text="monthLabel()"></h2><button type="button" @click="month(1)" aria-label="ماه بعد"><x-icon name="chevron-left" size="20" /></button></div><table class="admin-jalali-calendar-grid"><thead><tr>@foreach(['ش','ی','د','س','چ','پ','ج'] as $day)<th>{{ $day }}</th>@endforeach</tr></thead><tbody><template x-for="(week,index) in weeks" :key="index"><tr><template x-for="(day,col) in week" :key="col"><td><button class="admin-jalali-calendar-cell" type="button" x-show="day" :data-selected="day===Number(digits(parts.d))&&year===Number(digits(parts.y))&&mon===Number(digits(parts.m))||null" @click="select(day)" x-text="formatNumber(day)"></button></td></template></tr></template></tbody></table><div class="admin-jalali-calendar-actions"><button type="button" @click="today()">{{ ($withTime??false)?'اکنون':'امروز' }}</button><button type="button" @click="opened=false">بستن</button></div><p class="admin-jalali-calendar-tip">سال، ماه و روز را می‌توانید مستقیم در ورودی تایپ کنید.</p></div></div></div>
